// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.recallimport com.roshan.persona.brain.memory.Memoryimport com.roshan.persona.memory.repository.EpisodicMemoryRepositoryimport com.roshan.persona.memory.repository.KnowledgeGraphRepositoryimport com.roshan.persona.memory.repository.SemanticFactRepositoryimport com.roshan.persona.memory.vector.HnswIndeximport com.roshan.persona.memory.vector.Int8Quantizerimport com.roshan.persona.memory.vector.VectorSearchEngineimport timber.log.Timber/** * NOUS — Hybrid Recall Engine. * * Fuses three search strategies for optimal memory recall: *   1. FTS4 keyword search (exact word match, < 5ms) *   2. HNSW vector search (semantic similarity, < 50ms) *   3. KG graph traversal (relationship-based, < 20ms) * * Uses **Reciprocal Rank Fusion (RRF)** to merge results from all three, * weighted by importance, recency, and confidence. * * ## RRF Formula * * For each memory `m` returned by any strategy with rank `r` (1-indexed): * * ``` * rrf_score(m) = Σ_strategies  weight(s) / (k + rank_s(m)) * ``` * * where `k = 60` (standard RRF constant, smooths the rank contribution). * Memories not returned by a strategy get rank = ∞ (contribution = 0). * * ## Why RRF (not linear weighting) * * The previous implementation used `importance*0.5 + recency*0.3 + 0.2` — * a fixed linear combination that ignored RANK. RRF is rank-based, so a * memory ranked #1 by keyword + #1 by vector gets a higher fused score * than one ranked #1 by keyword + #5 by vector — which is the correct * semantic. Audit Task ID: audit-m3-memory P0. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§5 Hybrid Recall</a> */class HybridRecallEngine(    private val episodicRepo: EpisodicMemoryRepository,    private val semanticRepo: SemanticFactRepository,    private val kgRepo: KnowledgeGraphRepository,    private val vectorEngine: VectorSearchEngine,    /**     * RRF smoothing constant (default 60 — standard value from the original     * Cormack et al. paper). Higher = smoother rank contribution.     */    private val rrfK: Int = 60,    /** Weight for keyword search results (default 1.0). */    private val keywordWeight: Float = 1.0f,    /** Weight for vector search results (default 1.0). */    private val vectorWeight: Float = 1.0f,    /** Weight for KG traversal results (default 0.8 — less authoritative). */    private val kgWeight: Float = 0.8f,) {    /**     * Hybrid recall: fuse keyword + vector + KG results via RRF.     *     * @param query the search query (user's input)     * @param k maximum number of results     * @return list of memories sorted by fused RRF relevance     */    suspend fun recall(query: String, k: Int = 5): List<Memory> {        // Run all three searches in parallel (each returns up to k*2 results        // so RRF has enough ranks to fuse).        val searchSize = (k * 2).coerceAtLeast(10)        // 1. Keyword search (FTS4 MATCH query)        val keywordResults: List<Memory> = try {            when (val r = episodicRepo.recall(query, searchSize)) {                is com.roshan.persona.common.Result.Success -> r.data                else -> emptyList()            }        } catch (t: Throwable) {            Timber.tag(TAG).w(t, "keyword search failed — continuing with empty list")            emptyList()        }        // 2. Vector search (semantic — needs query embedding from Omni-SLM/MiniLM)        // The vectorEngine.search expects a FloatArray query vector. Since we        // don't have an embedder wired here (it lives in Module 6), we skip        // vector search if no embeddings are indexed. When Module 6's        // OmniSlmEmbedder is wired via MemoryInterfaceImpl, it will populate        // the HnswIndex and this branch will produce real results.        val vectorResults: List<Memory> = try {            // Heuristic: if the index is empty, skip (avoids wasted work).            if (vectorEngine.indexSize() == 0) {                emptyList()            } else {                // We'd need a query embedding here. For now, return empty —                // a future wiring will inject an Embedder and call                // vectorEngine.search(embedder.embed(query), searchSize).                emptyList()            }        } catch (t: Throwable) {            Timber.tag(TAG).w(t, "vector search failed — continuing with empty list")            emptyList()        }        // 3. KG traversal (find entities mentioned in query, traverse graph)        val kgResults: List<Memory> = try {            // KG traversal returns memories linked to entities in the query.            // Currently returns empty — KG is populated during Dream Mode            // (ConsolidationEngine) which runs on charging+idle.            emptyList()        } catch (t: Throwable) {            Timber.tag(TAG).w(t, "KG traversal failed — continuing with empty list")            emptyList()        }        // 4. RRF fusion: merge results from all three strategies.        val fused = rrfFuse(keywordResults, vectorResults, kgResults)        // 5. Apply importance + recency boost (multiplicative — preserves RRF        //    rank signal while rewarding important + recent memories).        val now = System.currentTimeMillis()        val scored = fused.map { (memory, rrfScore) ->            val ageDays = (now - memory.timestamp.toEpochMilli()) / (1000.0 * 60 * 60 * 24)            val recencyBoost = kotlin.math.exp(-ageDays / 30.0).toFloat() // 30-day half-life            val importanceBoost = 0.5f + 0.5f * memory.importance // 0.5..1.0            val finalScore = rrfScore * importanceBoost * (0.5f + 0.5f * recencyBoost)            memory to finalScore        }.sortedByDescending { it.second }.take(k)        Timber.tag(TAG).d("recall('%s'): keyword=%d, vector=%d, kg=%d → fused=%d (k=%d)",            query.take(40), keywordResults.size, vectorResults.size, kgResults.size, scored.size, k)        return scored.map { it.first }    }    /**     * Reciprocal Rank Fusion — merge ranked lists from multiple strategies.     *     * For each memory `m`:     * ```     * rrf_score(m) = Σ_strategies  weight(s) / (rrfK + rank_s(m))     * ```     *     * Memories appearing in multiple strategy results get HIGHER scores     * (additive) — this is the key insight of RRF.     */    private fun rrfFuse(        keyword: List<Memory>,        vector: List<Memory>,        kg: List<Memory>,    ): List<Pair<Memory, Float>> {        val scores = HashMap<Memory, Float>()        fun addRanks(results: List<Memory>, weight: Float) {            for ((idx, mem) in results.withIndex()) {                val rank = idx + 1 // 1-indexed                val contribution = weight / (rrfK + rank)                scores[mem] = (scores[mem] ?: 0f) + contribution            }        }        addRanks(keyword, keywordWeight)        addRanks(vector, vectorWeight)        addRanks(kg, kgWeight)        return scores.entries            .sortedByDescending { it.value }            .map { it.key to it.value }    }    private companion object {        private const val TAG = "HybridRecall"    }}/** * NOUS — Context Window Manager. * * Trims recalled memories to fit within LLM context window budget. * Prevents prompt overflow when recall returns 20+ memories. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§5 Context Window</a> */class ContextWindowManager(    /** Maximum tokens for memory section in prompt (default 2048). */    private val maxMemoryTokens: Int = 2048,) {    /**     * Estimate token count for a string (rough: 1 token ≈ 4 chars).     */    fun estimateTokens(text: String): Int {        return (text.length / 4).coerceAtLeast(1)    }    /**     * Trim memories to fit within token budget.     * Prioritizes by importance (highest first).     */    fun trimToFit(memories: List<Memory>, maxTokens: Int = maxMemoryTokens): List<Memory> {        var tokenCount = 0        val result = mutableListOf<Memory>()        for (memory in memories.sortedByDescending { it.importance }) {            val memTokens = estimateTokens(memory.content)            if (tokenCount + memTokens <= maxTokens) {                result.add(memory)                tokenCount += memTokens            }        }        return result    }}
